-- 0076 適用後チェック（SELECT1文・読み取り専用）。PASS/FAIL/INFO、最終行が総合判定。
with f as (select * from pg_proc p where p.oid = to_regprocedure('public.save_stylist_profile_v4(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text,text,date,integer,text)')),
r(ord, level, item, detail) as (values
 (1, case when exists (select 1 from f) then 'PASS' else 'FAIL' end, '保存関数 save_stylist_profile_v4 がある', ''),
 (2, case when (select prosecdef and exists (select 1 from unnest(coalesce(proconfig,'{}')) c where c like 'search_path=%') from f) then 'PASS' else 'FAIL' end, 'SECURITY DEFINER で search_path を固定', ''),
 (3, case when (select has_function_privilege('authenticated', oid, 'execute') and not has_function_privilege('anon', oid, 'execute') and not has_function_privilege('service_role', oid, 'execute') and not exists (select 1 from aclexplode(coalesce(proacl, acldefault('f', proowner))) a where a.grantee = 0) from f) then 'PASS' else 'FAIL' end, 'v4の実行権限は authenticated だけ', ''),
 (4, case when not has_function_privilege('authenticated', to_regprocedure('public.save_stylist_profile_v2(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text)'), 'execute') and not has_function_privilege('authenticated', to_regprocedure('public.set_stylist_career_phase(text,date,text,date,text)'), 'execute') then 'PASS' else 'FAIL' end, '旧経路（v2・set_stylist_career_phase）は閉じたまま', ''),
 (5, case when (select count(*)=2 from information_schema.columns where table_schema='public' and table_name='stylist_profiles' and column_name in ('blank_period_value','blank_period_unit')) and (select count(*) = 3 from pg_constraint where conrelid='public.stylist_profiles'::regclass and conname in ('stylist_profiles_blank_period_pair','stylist_profiles_blank_period_unit_check','stylist_profiles_career_phase_consistent')) and not exists (select 1 from pg_constraint where conname='stylist_profiles_start_after_graduation' and conrelid='public.stylist_profiles'::regclass) then 'PASS' else 'FAIL' end, 'ブランク期間の列・制約がある／整合制約が置き換わり、就業開始の制約が外れている', ''),
 (6, case when (select count(*)=2 from pg_trigger where tgrelid='public.stylist_profiles'::regclass and tgname in ('trg_graduation_month_valid','trg_blank_period_follow_phase')) and exists (select 1 from pg_trigger where tgname='trg_career_phase_valid' and tgrelid='public.stylist_profiles'::regclass) and exists (select 1 from pg_trigger where tgname='trg_career_phase_required_on_insert' and tgrelid='public.stylist_profiles'::regclass) then 'PASS' else 'FAIL' end, '卒業月・ブランク期間のトリガーがあり、既存の立場トリガー（0073・0074）も残っている', ''),
 (7, case when (select lower(prosrc) not like '%graduation_kind%' and lower(prosrc) not like '%desired_start%' and lower(prosrc) not like '%license_status%' and lower(prosrc) like '%in (3, 10)%' from f) then 'PASS' else 'FAIL' end, '静的確認: v4は旧3項目を参照せず、月は3・10だけ', ''),
 (8, case when to_regprocedure('public.set_stylist_value_priorities(text[])') is not null and to_regprocedure('public.save_stylist_profile_v3(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text,text,date,text,date,text)') is not null then 'PASS' else 'FAIL' end, '0072の専用保存・v3（0077で閉じるまで）が変わらずある', ''),
 (9, 'INFO', '立場の内訳（適用前と同じはず。0076はデータを変更しない）', (select count(*) filter (where career_phase is null)::text||' / '||count(*) filter (where career_phase='student')::text||' / '||count(*) filter (where career_phase='new_graduate')::text||' / '||count(*) filter (where career_phase='experienced')::text||' / '||count(*) filter (where career_phase='blank')::text from public.stylist_profiles)),
 (10, 'INFO', '旧3項目が入っている行数（適用前と同じはず）', (select count(*) filter (where graduation_kind is not null)::text||' / '||count(*) filter (where desired_start_ym is not null)::text||' / '||count(*) filter (where license_status is not null)::text from public.stylist_profiles)),
 (11, 'INFO', 'ブランク期間が入っている行数（適用直後は0のはず）', (select count(*)::text from public.stylist_profiles where blank_period_value is not null))
)
select ord, level, item, detail from (select ord::text as ord, level, item, detail from r
union all
select '99', case when (select count(*) from r where level='FAIL')=0 then 'PASS' else 'FAIL' end, '総合判定（INFO '||(select count(*) from r where level='INFO')||'件は人が確認）', 'FAIL '||(select count(*) from r where level='FAIL')||'件'
) t order by ord::int;
